def replace_one(html, plate, revised):
    # Match only the original Batch-2 candidate, never a prior revised state.
    pat=re.compile(r'<figure class="sys-fig v188-pencil-plate" data-v188-plate="'+re.escape(plate)+r'">.*?</figure>',re.S)
    out,n=pat.subn(revised,html,count=1)
    if n!=1: raise RuntimeError(f'{plate}: expected exactly one original candidate, found {n}')
    return out

def main(root):
    root=Path(root)
    targets=[root/'academic_payload/index.html',root/'app/src/main/assets/www/index.html']
    for p in targets:
        if not p.exists(): raise FileNotFoundError(p)
        s=p.read_text(encoding='utf-8')
        for plate,revised in REV.items(): s=replace_one(s,plate,revised)
        p.write_text(s,encoding='utf-8')
    if targets[0].read_bytes()!=targets[1].read_bytes(): raise RuntimeError('payload copies diverged')
    print('Earthworm targeted remediation applied: external, digestive, vascular, excretory, reproductive. Nervous anatomy unchanged.')

if __name__=='__main__':
    if len(sys.argv)!=2: raise SystemExit('usage: reconcile_v188_earthworm_remediation.py <source-root>')
    main(sys.argv[1])
